from ._gen import *
MORE_FOR = 'cr11_monthly_reporting_pack'
PROBLEMS = []
ME = ['2025-01-31','2025-02-28','2025-03-31','2025-04-30','2025-05-31','2025-06-30','2025-07-31','2025-08-31','2025-09-30','2025-10-31','2025-11-30','2025-12-31']
for d in ME:
    PROBLEMS.append(P(2, f"KPI row for the month ending {d}: live loans, balance (0 dp), 30+ DPD rate (count, 2 dp %), 90+ DPD rate (count, 2 dp %), new loans originated in that month, new lending (0 dp). `live_loans`, `balance`, `pct_30plus`, `pct_90plus`, `new_loans`, `new_amount`.",
      f"SELECT (SELECT COUNT(*) FROM loan_monthly_snapshot WHERE snapshot_date=DATE '{d}' AND loan_status<>'Closed'), (SELECT ROUND(SUM(closing_balance),0) FROM loan_monthly_snapshot WHERE snapshot_date=DATE '{d}' AND loan_status<>'Closed'), (SELECT ROUND(100.0*COUNT(*) FILTER (WHERE days_past_due>=30)/COUNT(*),2) FROM loan_monthly_snapshot WHERE snapshot_date=DATE '{d}' AND loan_status<>'Closed'), (SELECT ROUND(100.0*COUNT(*) FILTER (WHERE days_past_due>=90)/COUNT(*),2) FROM loan_monthly_snapshot WHERE snapshot_date=DATE '{d}' AND loan_status<>'Closed'), (SELECT COUNT(*) FROM loan WHERE origination_date>date_trunc('month', DATE '{d}')-INTERVAL 1 DAY AND origination_date<=DATE '{d}'), (SELECT ROUND(SUM(original_amount),0) FROM loan WHERE origination_date>date_trunc('month', DATE '{d}')-INTERVAL 1 DAY AND origination_date<=DATE '{d}')"))
for y in range(2019,2026):
    PROBLEMS.append(P(3, f"Executive summary for {y}-12-31: live loans, balance in $m (1 dp), 90+ DPD rate (2 dp %), ECL in $m (1 dp), coverage (2 dp %), new lending in {y} in $m (1 dp). `live_loans`, `balance_m`, `pct_90plus`, `ecl_m`, `coverage_pct`, `new_lending_m`.",
      f"SELECT (SELECT COUNT(*) FROM loan_monthly_snapshot WHERE snapshot_date=DATE '{y}-12-31' AND loan_status<>'Closed'), (SELECT ROUND(SUM(closing_balance)/1e6,1) FROM loan_monthly_snapshot WHERE snapshot_date=DATE '{y}-12-31' AND loan_status<>'Closed'), (SELECT ROUND(100.0*COUNT(*) FILTER (WHERE days_past_due>=90)/COUNT(*),2) FROM loan_monthly_snapshot WHERE snapshot_date=DATE '{y}-12-31' AND loan_status<>'Closed'), (SELECT ROUND(SUM(ecl_amount)/1e6,1) FROM ecl_provision_quarterly WHERE reporting_date=DATE '{y}-12-31'), (SELECT ROUND(100*SUM(ecl_amount)/SUM(ead),2) FROM ecl_provision_quarterly WHERE reporting_date=DATE '{y}-12-31'), (SELECT ROUND(SUM(original_amount)/1e6,1) FROM loan WHERE {yr('origination_date',y)})"))
